+const DEFAULT_SOURCE = Object.freeze({
+  actividades: [],
+  lugares: []
+});
+
+function normalizeItems(items, tipo) {
+  if (!Array.isArray(items)) return [];
+
+  return items
+    .filter((item) => item && item.favorito === true)
+    .map((item) => ({
+      ...item,
+      tipo
+    }));
+}
+
+export function listarFavoritos({ actividades, lugares } = DEFAULT_SOURCE) {
+  return [
+    ...normalizeItems(lugares, "lugar"),
+    ...normalizeItems(actividades, "actividad")
+  ];
+}
+
