+  const resultado = listarFavoritos({
+    lugares: [
+      { id: "l-1", nombre: "Parque Central", favorito: true },
+      { id: "l-2", nombre: "Museo de Historia", favorito: false }
+    ],
+    actividades: [
+      { id: "a-1", nombre: "Paseo en bici", favorito: true },
+      { id: "a-2", nombre: "Picnic", favorito: false }
+    ]
+  });
+
+  assert.deepEqual(resultado, [
+    { id: "l-1", nombre: "Parque Central", favorito: true, tipo: "lugar" },
+    { id: "a-1", nombre: "Paseo en bici", favorito: true, tipo: "actividad" }
+  ]);
+});
+
+test("ignora colecciones ausentes o no marcadas como favoritas", () => {
+  assert.deepEqual(listarFavoritos(), []);
+  assert.deepEqual(
+    listarFavoritos({
+      lugares: [{ id: "l-1", nombre: "Parque Central", favorito: false }],
+      actividades: [{ id: "a-1", nombre: "Paseo en bici" }]
+    }),
+    []
+  );
+});

