+import assert from "node:assert/strict";
+import test from "node:test";
+import { cargarGasto, crearPresupuesto } from "./budget.mjs";
+
+test("el presupuesto total, los gastos por categoría y el disponible se calculan correctamente", () => {
+  const presupuesto = crearPresupuesto(1000, {
+    alojamiento: 350,
+    comida: 125,
+    transporte: 75,
+  });
+
+  assert.equal(presupuesto.total, 1000);
+  assert.deepEqual(presupuesto.gastosPorCategoria, {
+    alojamiento: 350,
+    comida: 125,
+    transporte: 75,
+  });
+  assert.equal(presupuesto.gastado, 550);
+  assert.equal(presupuesto.disponible, 450);
+});
+
+test("cargarGasto acumula los gastos por categoría y actualiza gastado y disponible", () => {
+  const presupuestoInicial = crearPresupuesto(500);
+  const presupuestoActualizado = cargarGasto(presupuestoInicial, "comida", 120);
+  const presupuestoFinal = cargarGasto(presupuestoActualizado, "comida", 30);
+
+  assert.deepEqual(presupuestoActualizado, {
+    total: 500,
+    gastosPorCategoria: {
+      comida: 120,
+    },
+    gastado: 120,
+    disponible: 380,
+  });
+  assert.deepEqual(presupuestoFinal, {
+    total: 500,
+    gastosPorCategoria: {
+      comida: 150,
+    },
+    gastado: 150,
+    disponible: 350,
+  });
+});

