@@ -0,0 +1,75 @@
+function ensureFiniteNumber(value, name) {
+  if (typeof value !== "number" || !Number.isFinite(value)) {
+    throw new TypeError(`${name} must be a finite number`);
+  }
+
+  return value;
+}
+
+function normalizeCategoryAmount(amount, category) {
+  return ensureFiniteNumber(amount, `gasto for category "${category}"`);
+}
+
+function normalizeExpenses(gastosPorCategoria) {
+  if (Array.isArray(gastosPorCategoria)) {
+    return Object.fromEntries(
+      gastosPorCategoria.map(([categoria, monto]) => [categoria, normalizeCategoryAmount(monto, categoria)]),
+    );
+  }
+
+  if (gastosPorCategoria && typeof gastosPorCategoria === "object") {
+    return Object.fromEntries(
+      Object.entries(gastosPorCategoria).map(([categoria, monto]) => [
+        categoria,
+        normalizeCategoryAmount(monto, categoria),
+      ]),
+    );
+  }
+
+  return {};
+}
+
+function sumExpenses(gastosPorCategoria) {
+  return Object.values(gastosPorCategoria).reduce((total, monto) => total + monto, 0);
+}
+
+export function crearPresupuesto(total, gastosPorCategoria = {}) {
+  const presupuestoTotal = ensureFiniteNumber(total, "total");
+  const gastosNormalizados = normalizeExpenses(gastosPorCategoria);
+  const gastado = sumExpenses(gastosNormalizados);
+
+  return {
+    total: presupuestoTotal,
+    gastosPorCategoria: gastosNormalizados,
+    gastado,
+    disponible: presupuestoTotal - gastado,
+  };
+}
+
+export function cargarGasto(presupuesto, categoria, monto) {
+  if (!presupuesto || typeof presupuesto !== "object") {
+    throw new TypeError("presupuesto must be an object");
+  }
+
+  if (typeof categoria !== "string" || categoria.trim() === "") {
+    throw new TypeError("categoria must be a non-empty string");
+  }
+
+  const gasto = ensureFiniteNumber(monto, "monto");
+  const gastosPorCategoria = {
+    ...(presupuesto.gastosPorCategoria ?? {}),
+    [categoria]: (presupuesto.gastosPorCategoria?.[categoria] ?? 0) + gasto,
+  };
+
+  return crearPresupuesto(presupuesto.total, gastosPorCategoria);
+}
+
+export const agregarGasto = cargarGasto;
+export const calcularPresupuesto = crearPresupuesto;
+
+export default {
+  crearPresupuesto,
+  cargarGasto,
+  agregarGasto,
+  calcularPresupuesto,
+};
