+export const storageKey = "viaje-en-familia";
+
+function getLocalStorage() {
+  const { localStorage } = globalThis;
+
+  if (!localStorage) {
+    throw new Error("localStorage is not available");
+  }
+
+  return localStorage;
+}
+
+export function loadTripState() {
+  const rawState = getLocalStorage().getItem(storageKey);
+
+  if (rawState === null) {
+    return null;
+  }
+
+  try {
+    return JSON.parse(rawState);
+  } catch {
+    return null;
+  }
+}
+
+export function saveTripState(state) {
+  getLocalStorage().setItem(storageKey, JSON.stringify(state));
+}
