+import assert from "node:assert/strict";
+import test from "node:test";
+
+function createLocalStorage() {
+  const store = new Map();
+
+  return {
+    getItem(key) {
+      return store.has(key) ? store.get(key) : null;
+    },
+    setItem(key, value) {
+      store.set(key, String(value));
+    },
+    removeItem(key) {
+      store.delete(key);
+    },
+    clear() {
+      store.clear();
+    },
+  };
+}
+
+async function importFreshStorageModule() {
+  const url = new URL("./storage.mjs", import.meta.url);
+  url.searchParams.set("t", String(Math.random()));
+  return import(url.href);
+}
+
+test("loadTripState returns null when there is no saved state", async () => {
+  globalThis.localStorage = createLocalStorage();
+
+  const { loadTripState } = await importFreshStorageModule();
+
+  assert.equal(loadTripState(), null);
+});
+
+test("saveTripState persists state in localStorage and loadTripState reads it back", async () => {
+  globalThis.localStorage = createLocalStorage();
+
+  const { loadTripState, saveTripState, storageKey } = await importFreshStorageModule();
+  const state = {
+    destination: "Bariloche",
+    travelers: 4,
+    itinerary: ["Llegada", "Excursión"],
+  };
+
+  saveTripState(state);
+
+  assert.equal(globalThis.localStorage.getItem(storageKey), JSON.stringify(state));
+  assert.deepEqual(loadTripState(), state);
+});
+
+test("saved state survives a module reload because it is stored in localStorage", async () => {
+  globalThis.localStorage = createLocalStorage();
+
+  const firstModule = await importFreshStorageModule();
+  const state = {
+    destination: "Mendoza",
+    travelers: 2,
+    budget: 350000,
+  };
+
+  firstModule.saveTripState(state);
+
+  const secondModule = await importFreshStorageModule();
+
+  assert.deepEqual(secondModule.loadTripState(), state);
+});

