+import assert from "node:assert/strict";
+import test from "node:test";
+
+import { addStop, editStop, removeStop, reorderStops, stopFields } from "./stops.mjs";
+
+function makeStop(overrides = {}) {
+  return {
+    id: "stop-1",
+    name: "Montevideo",
+    startDate: "2026-08-01",
+    endDate: "2026-08-03",
+    description: "Base de partida",
+    order: 1,
+    ...overrides
+  };
+}
+
+function assertStopShape(stop) {
+  assert.deepEqual(Object.keys(stop), ["id", "name", "startDate", "endDate", "description", "order"]);
+}
+
+test("exports the shared stop field contract", () => {
+  assert.deepEqual(stopFields, ["id", "name", "startDate", "endDate", "description", "order"]);
+});
+
+test("addStop creates a new ordered stop", () => {
+  const stops = [makeStop()];
+
+  const next = addStop(stops, {
+    name: "Colonia",
+    startDate: "2026-08-04",
+    endDate: "2026-08-05",
+    description: "Parada corta"
+  });
+
+  assert.equal(next.length, 2);
+  assertStopShape(next[0]);
+  assertStopShape(next[1]);
+  assert.equal(next[1].name, "Colonia");
+  assert.equal(next[1].order, 2);
+  assert.equal(typeof next[1].id, "string");
+  assert.equal(next[0].order, 1);
+});
+
+test("addStop can insert by requested order", () => {
+  const stops = [makeStop({ id: "a", order: 1 }), makeStop({ id: "c", order: 2, name: "Punta del Este" })];
+
+  const next = addStop(stops, {
+    name: "Maldonado",
+    startDate: "2026-08-02",
+    endDate: "2026-08-02",
+    description: "Inserción intermedia",
+    order: 2
+  });
+
+  assert.deepEqual(next.map((stop) => stop.name), ["Montevideo", "Maldonado", "Punta del Este"]);
+  assert.deepEqual(next.map((stop) => stop.order), [1, 2, 3]);
+});
+
+test("editStop updates fields and preserves order by default", () => {
+  const stops = [makeStop(), makeStop({ id: "stop-2", order: 2, name: "Punta del Este" })];
+
+  const next = editStop(stops, "stop-2", {
+    name: "Punta Ballena",
+    description: "Nombre corregido"
+  });
+
+  assert.deepEqual(next.map((stop) => stop.order), [1, 2]);
+  assert.equal(next[1].name, "Punta Ballena");
+  assert.equal(next[1].description, "Nombre corregido");
+  assertStopShape(next[1]);
+});
+
+test("editStop can move a stop when order is provided", () => {
+  const stops = [
+    makeStop({ id: "a", name: "A", order: 1 }),
+    makeStop({ id: "b", name: "B", order: 2 }),
+    makeStop({ id: "c", name: "C", order: 3 })
+  ];
+
+  const next = editStop(stops, "b", { order: 1, description: "Reubicada" });
+
+  assert.deepEqual(next.map((stop) => stop.name), ["B", "A", "C"]);
+  assert.deepEqual(next.map((stop) => stop.order), [1, 2, 3]);
+  assert.equal(next[0].description, "Reubicada");
+});
+
+test("removeStop deletes a stop and compacts orders", () => {
+  const stops = [
+    makeStop({ id: "a", name: "A", order: 1 }),
+    makeStop({ id: "b", name: "B", order: 2 }),
+    makeStop({ id: "c", name: "C", order: 3 })
+  ];
+
+  const next = removeStop(stops, "b");
+
+  assert.deepEqual(next.map((stop) => stop.name), ["A", "C"]);
+  assert.deepEqual(next.map((stop) => stop.order), [1, 2]);
+});
+
+test("reorderStops moves by 1-based positions", () => {
+  const stops = [
+    makeStop({ id: "a", name: "A", order: 1 }),
+    makeStop({ id: "b", name: "B", order: 2 }),
+    makeStop({ id: "c", name: "C", order: 3 })
+  ];
+
+  const next = reorderStops(stops, 1, 3);
+
+  assert.deepEqual(next.map((stop) => stop.name), ["B", "C", "A"]);
+  assert.deepEqual(next.map((stop) => stop.order), [1, 2, 3]);
+});
+
+test("reorderStops also accepts ids", () => {
+  const stops = [
+    makeStop({ id: "a", name: "A", order: 1 }),
+    makeStop({ id: "b", name: "B", order: 2 }),
+    makeStop({ id: "c", name: "C", order: 3 })
