+const DEFAULT_LABEL = "Item";
+
+function normalizeLabel(value) {
+  if (typeof value === "string") {
+    const label = value.trim();
+    if (label.length > 0) return label;
+  }
+
+  if (value && typeof value === "object") {
+    const candidate = value.label ?? value.nombre ?? value.name ?? value.text;
+    if (typeof candidate === "string") {
+      const label = candidate.trim();
+      if (label.length > 0) return label;
+    }
+  }
+
+  return DEFAULT_LABEL;
+}
+
+function normalizeCompleted(value) {
+  if (typeof value === "boolean") return value;
+  if (value && typeof value === "object") {
+    if (typeof value.completed === "boolean") return value.completed;
+    if (typeof value.completado === "boolean") return value.completado;
+    if (typeof value.done === "boolean") return value.done;
+  }
+  return false;
+}
+
+function normalizeItem(value) {
+  if (typeof value === "string") {
+    return { label: normalizeLabel(value), completed: false };
+  }
+
+  if (value && typeof value === "object") {
+    return {
+      label: normalizeLabel(value),
+      completed: normalizeCompleted(value)
+    };
+  }
+
+  return { label: DEFAULT_LABEL, completed: false };
+}
+
+function matchesQuery(item, query) {
+  if (typeof query !== "string") return true;
+  const needle = query.trim().toLowerCase();
+  if (needle.length === 0) return true;
+  return item.label.toLowerCase().includes(needle);
+}
+
+function matchesCompleted(item, filter) {
+  if (typeof filter === "boolean") return item.completed === filter;
+  if (typeof filter === "string") {
+    const normalized = filter.trim().toLowerCase();
+    if (normalized === "completed" || normalized === "completado") {
+      return item.completed;
+    }
+    if (normalized === "pending" || normalized === "pendiente") {
+      return !item.completed;
+    }
+  }
+  return true;
+}
+
+function resolveChecklist(checklist) {
+  if (!checklist || typeof checklist !== "object" || !Array.isArray(checklist.items)) {
+    throw new TypeError("A packing checklist with an items array is required.");
+  }
+  return checklist;
+}
+
+function findItemIndex(items, target) {
+  if (typeof target === "string") {
+    const normalized = target.trim().toLowerCase();
+    return items.findIndex((item) => item.label.toLowerCase() === normalized);
+  }
+
+  if (target && typeof target === "object") {
+    if (typeof target.label === "string") {
+      return findItemIndex(items, target.label);
+    }
+    if (typeof target.nombre === "string") {
+      return findItemIndex(items, target.nombre);
+    }
+    if (typeof target.name === "string") {
+      return findItemIndex(items, target.name);
+    }
+  }
+
+  return -1;
+}
+
+export function crearChecklistEquipaje(initialItems = []) {
+  const items = initialItems.map(normalizeItem);
+
+  const checklist = {
+    items,
+    agregarItem(item) {
+      const normalized = normalizeItem(item);
+      items.push(normalized);
+      return normalized;
+    },
+    addItem(item) {
+      return checklist.agregarItem(item);
+    },
+    completarItem(target) {
+      const index = findItemIndex(items, target);
+      if (index === -1) return null;
+      items[index] = { ...items[index], completed: true };
+      return items[index];
+    },
+    completeItem(target) {
+      return checklist.completarItem(target);
+    },
+    filtrarItems(filter = {}) {
+      const query = filter.query ?? filter.buscar ?? filter.search ?? "";
+      const completedFilter = filter.completed ?? filter.completado ?? filter.estado ?? filter.status;
+
+      return items.filter((item) => matchesQuery(item, query) && matchesCompleted(item, completedFilter));
+    },
+    filterItems(filter = {}) {
+      return checklist.filtrarItems(filter);
+    },
+    calcularProgresoTotal() {
+      const total = items.length;
+      if (total === 0) return 0;
+
+      const completed = items.filter((item) => item.completed).length;
+      return Math.round((completed / total) * 100);
+    },
+    calculateTotalProgress() {
+      return checklist.calcularProgresoTotal();
+    }
+  };
+
+  return checklist;
+}
+
+export const createPackingChecklist = crearChecklistEquipaje;
+
+export function agregarItem(checklist, item) {
+  return resolveChecklist(checklist).agregarItem(item);
+}
+
+export function addItem(checklist, item) {
+  return agregarItem(checklist, item);
+}
+
+export function completarItem(checklist, target) {
+  return resolveChecklist(checklist).completarItem(target);
+}
+
+export function completeItem(checklist, target) {
+  return completarItem(checklist, target);
+}
+
+export function filtrarItems(checklist, filter = {}) {
+  return resolveChecklist(checklist).filtrarItems(filter);
+}
+
+export function filterItems(checklist, filter = {}) {
+  return filtrarItems(checklist, filter);
+}
+
+export function calcularProgresoTotal(checklist) {
+  return resolveChecklist(checklist).calcularProgresoTotal();
+}
+
+export function calculateTotalProgress(checklist) {
+  return calcularProgresoTotal(checklist);
+}
+
+export default crearChecklistEquipaje;
