+  const next = normalizeStops(stops);
+  const [item] = next.splice(fromIndex, 1);
+  const insertionIndex = clamp(toIndex, 0, next.length);
+  next.splice(insertionIndex, 0, item);
+
+  return next.map((entry, index) => ({
+    id: entry.id,
+    name: entry.name,
+    startDate: entry.startDate,
+    endDate: entry.endDate,
+    description: entry.description,
+    order: index + 1
+  }));
+}
+
+function locateStop(stops, stopId) {
+  const normalized = normalizeStops(stops);
+  const index = findStopIndex(normalized, stopId);
+  if (index < 0) {
+    throw new RangeError(`Stop not found: ${stopId}`);
+  }
+
+  return { normalized, index };
+}
+
+export function addStop(stops, stop) {
+  const normalized = normalizeStops(stops);
+  const nextStop = buildStop(stop, Number.isFinite(stop?.order) ? stop.order : normalized.length + 1, stop?.id);
