+  next.splice(index, 1);
+
+  if (changes && Object.prototype.hasOwnProperty.call(changes, "order")) {
+    return insertAtOrder(next, updated, changes.order);
+  }
+
+  next.splice(index, 0, updated);
+  return next.map((entry, position) => ({
+    id: entry.id,
+    name: entry.name,
+    startDate: entry.startDate,
+    endDate: entry.endDate,
+    description: entry.description,
+    order: position + 1
+  }));
+}
+
+export function removeStop(stops, stopId) {
+  const normalized = normalizeStops(stops);
+  const index = findStopIndex(normalized, stopId);
+  if (index < 0) {
+    throw new RangeError(`Stop not found: ${stopId}`);
+  }
+
+  return normalized
+    .filter((_, position) => position !== index)
+    .map((entry, position) => ({
+      id: entry.id,
+      name: entry.name,
+      startDate: entry.startDate,
+      endDate: entry.endDate,
+      description: entry.description,
+      order: position + 1
+    }));
+}
+
+export function reorderStops(stops, source, target) {
+  const normalized = normalizeStops(stops);
+  const { fromIndex, toIndex } = resolveMoveIndexes(normalized, source, target);
+  if (fromIndex < 0 || fromIndex >= normalized.length) {
+    throw new RangeError(`Stop not found at source position: ${fromIndex}`);
+  }
