+import { randomUUID } from "node:crypto";
+
+const NOTE_KEYS = ["id", "text", "dayId", "stopId", "createdAt", "updatedAt"];
+
+function cloneNote(note) {
+  return {
+    id: note.id,
+    text: note.text,
+    dayId: note.dayId ?? null,
+    stopId: note.stopId ?? null,
+    createdAt: note.createdAt,
+    updatedAt: note.updatedAt
+  };
+}
+
+function normalizeAssociation(input = {}) {
+  const dayId = input.dayId ?? input.diaId ?? null;
+  const stopId = input.stopId ?? input.paradaId ?? null;
+  const hasDay = dayId !== null && dayId !== undefined;
+  const hasStop = stopId !== null && stopId !== undefined;
+
+  if (hasDay === hasStop) {
+    throw new TypeError("A note must be associated with exactly one day or stop.");
+  }
+
+  return {
+    dayId: hasDay ? String(dayId) : null,
+    stopId: hasStop ? String(stopId) : null
+  };
+}
+
+function normalizeText(input = {}) {
+  const value = input.text ?? input.texto;
+  if (typeof value !== "string") {
+    throw new TypeError("A note needs text.");
+  }
+  const text = value.trim();
+  if (!text) {
+    throw new TypeError("A note needs text.");
+  }
+  return text;
+}
+
+function normalizeId(id) {
+  if (typeof id !== "string") {
+    throw new TypeError("A note id must be a string.");
+  }
+  const value = id.trim();
+  if (!value) {
+    throw new TypeError("A note id must be a string.");
+  }
+  return value;
+}
+
+function normalizeNote(input, now = new Date()) {
+  if (!input || typeof input !== "object") {
+    throw new TypeError("A note must be an object.");
+  }
+
+  const association = normalizeAssociation(input);
+  const text = normalizeText(input);
+  const id = input.id ? normalizeId(input.id) : randomUUID();
+  const createdAt = typeof input.createdAt === "string" && input.createdAt ? input.createdAt : now.toISOString();
+  const updatedAt = typeof input.updatedAt === "string" && input.updatedAt ? input.updatedAt : createdAt;
+
+  return cloneNote({
+    id,
+    text,
+    ...association,
+    createdAt,
+    updatedAt
+  });
+}
+
+function applyPatch(existing, patch, now = new Date()) {
+  if (!patch || typeof patch !== "object") {
+    throw new TypeError("A note patch must be an object.");
+  }
+
+  const text = patch.text ?? patch.texto ?? existing.text;
+  const dayId = patch.dayId ?? patch.diaId;
+  const stopId = patch.stopId ?? patch.paradaId;
+  const hasAssociationChange = dayId !== undefined || stopId !== undefined;
+  let association = {
+    dayId: existing.dayId,
+    stopId: existing.stopId
+  };
+
+  if (hasAssociationChange) {
+    association = normalizeAssociation({
+      dayId: dayId !== undefined ? dayId : null,
+      stopId: stopId !== undefined ? stopId : null
+    });
+  }
+
+  return cloneNote({
+    ...existing,
+    text: normalizeText({ text }),
+    ...association,
+    updatedAt: now.toISOString()
+  });
+}
+
+function matchesFilter(note, filter = {}) {
+  if (filter.dayId !== undefined && String(filter.dayId) !== note.dayId) {
+    return false;
+  }
+  if (filter.stopId !== undefined && String(filter.stopId) !== note.stopId) {
+    return false;
+  }
+  return true;
+}
+
+export function createNote(input, now = new Date()) {
+  return normalizeNote(input, now);
+}
+
+export function updateNote(note, patch, now = new Date()) {
+  return applyPatch(normalizeNote(note, new Date(note.updatedAt ?? now)), patch, now);
+}
+
+export function associateNote(note, association, now = new Date()) {
+  return applyPatch(note, association, now);
+}
+
+export function disassociateNote(note, now = new Date()) {
+  if (!note || typeof note !== "object") {
+    throw new TypeError("A note must be an object.");
+  }
+  return cloneNote({
+    ...note,
+    dayId: null,
+    stopId: null,
+    updatedAt: now.toISOString()
+  });
+}
+
+export function listNotes(notes = [], filter = {}) {
+  return notes.filter((note) => matchesFilter(note, filter)).map(cloneNote);
+}
+
+export function listNotesForDay(notes = [], dayId) {
+  return listNotes(notes, { dayId });
+}
+
+export function listNotesForStop(notes = [], stopId) {
+  return listNotes(notes, { stopId });
+}
+
+export function getNote(notes = [], id) {
+  const noteId = normalizeId(id);
+  const found = notes.find((note) => note.id === noteId);
+  return found ? cloneNote(found) : null;
+}
+
+export function createNotesStore(initialNotes = []) {
+  const state = new Map();
+
+  for (const note of initialNotes) {
+    const normalized = normalizeNote(note);
+    state.set(normalized.id, normalized);
+  }
+
+  const store = {
+    save(input) {
+      if (input?.id) {
+        const noteId = normalizeId(input.id);
+        const existing = state.get(noteId);
+        const candidate = existing ? applyPatch(existing, input) : normalizeNote(input);
+        state.set(candidate.id, candidate);
+        return cloneNote(candidate);
+      }
+
+      const candidate = normalizeNote(input);
+      state.set(candidate.id, candidate);
+      return cloneNote(candidate);
+    },
+    update(id, patch) {
+      const noteId = normalizeId(id);
+      const existing = state.get(noteId);
+      if (!existing) {
+        throw new RangeError(`Note not found: ${noteId}`);
+      }
+      const updated = applyPatch(existing, patch);
+      state.set(noteId, updated);
+      return cloneNote(updated);
+    },
+    associate(id, association) {
+      return store.update(id, association);
+    },
+    disassociate(id) {
+      const noteId = normalizeId(id);
+      const existing = state.get(noteId);
+      if (!existing) {
+        throw new RangeError(`Note not found: ${noteId}`);
+      }
+      const updated = disassociateNote(existing);
+      state.set(noteId, updated);
+      return cloneNote(updated);
+    },
+    get(id) {
+      const noteId = normalizeId(id);
+      const note = state.get(noteId);
+      return note ? cloneNote(note) : null;
+    },
+    list(filter = {}) {
+      return listNotes([...state.values()], filter);
+    },
+    listForDay(dayId) {
+      return listNotesForDay([...state.values()], dayId);
+    },
+    listForStop(stopId) {
+      return listNotesForStop([...state.values()], stopId);
+    },
+    remove(id) {
+      const noteId = normalizeId(id);
+      const existing = state.get(noteId);
+      if (!existing) {
+        return false;
+      }
+      state.delete(noteId);
+      return true;
+    },
+    snapshot() {
+      return [...state.values()].map(cloneNote);
+    }
+  };
+
+  return store;
+}
+
+export const crearNota = createNote;
+export const actualizarNota = updateNote;
+export const asociarNota = associateNote;
+export const desasociarNota = disassociateNote;
+export const listarNotas = listNotes;
+export const listarNotasPorDia = listNotesForDay;
+export const listarNotasPorParada = listNotesForStop;
+export const obtenerNota = getNote;
+export const crearNotas = createNotesStore;
+export const notes = {
+  NOTE_KEYS,
+  createNote,
+  updateNote,
+  associateNote,
+  disassociateNote,
+  listNotes,
+  listNotesForDay,
+  listNotesForStop,
+  getNote,
+  createNotesStore,
+  crearNota,
+  actualizarNota,
+  asociarNota,
+  desasociarNota,
+  listarNotas,
+  listarNotasPorDia,
+  listarNotasPorParada,
+  obtenerNota,
+  crearNotas
+};
+
+export default {
+  NOTE_KEYS,
+  createNote,
+  updateNote,
+  associateNote,
+  disassociateNote,
+  listNotes,
+  listNotesForDay,
+  listNotesForStop,
+  getNote,
+  createNotesStore,
+  crearNota,
+  actualizarNota,
+  asociarNota,
+  desasociarNota,
+  listarNotas,
+  listarNotasPorDia,
+  listarNotasPorParada,
+  obtenerNota,
+  crearNotas,
+  notes
+};
diff --git a/src/recuerdos/notes/notes.test.mjs b/src/recuerdos/notes/notes.test.mjs
new file mode 100644
