--- /dev/null
+++ b/src/recuerdos/notes/notes.test.mjs
@@ -0,0 +1,77 @@
+import assert from "node:assert/strict";
+import test from "node:test";
+import {
+  associateNote,
+  createNote,
+  createNotesStore,
+  disassociateNote,
+  getNote,
+  listNotesForDay,
+  listNotesForStop,
+  updateNote
+} from "./notes.mjs";
+
+test("creates a note associated to a day", () => {
+  const note = createNote({ text: "Comprar agua", dayId: "day-1" });
+
+  assert.equal(note.text, "Comprar agua");
+  assert.equal(note.dayId, "day-1");
+  assert.equal(note.stopId, null);
+  assert.match(note.id, /^[0-9a-f-]{36}$/);
+  assert.ok(note.createdAt);
+  assert.equal(note.createdAt, note.updatedAt);
+});
+
+test("creates a note associated to a stop", () => {
+  const note = createNote({ texto: "Sacar foto", paradaId: "stop-9" });
+
+  assert.equal(note.text, "Sacar foto");
+  assert.equal(note.dayId, null);
+  assert.equal(note.stopId, "stop-9");
+});
+
+test("rejects notes without exactly one association", () => {
+  assert.throws(() => createNote({ text: "Sin destino" }), /exactly one day or stop/);
+  assert.throws(() => createNote({ text: "Dos destinos", dayId: "day-1", stopId: "stop-2" }), /exactly one day or stop/);
+});
+
+test("updates the note text and association", () => {
+  const created = createNote({ text: "Original", dayId: "day-1" });
+  const updated = updateNote(created, { text: "Editada", stopId: "stop-2" });
+
+  assert.equal(updated.id, created.id);
+  assert.equal(updated.text, "Editada");
+  assert.equal(updated.dayId, null);
+  assert.equal(updated.stopId, "stop-2");
+  assert.notEqual(updated.updatedAt, created.updatedAt);
+});
+
+test("associates and disassociates notes without losing the text", () => {
+  const created = createNote({ text: "Base", dayId: "day-1" });
+  const moved = associateNote(created, { stopId: "stop-3" });
+  const cleared = disassociateNote(moved);
+
+  assert.equal(moved.stopId, "stop-3");
+  assert.equal(moved.dayId, null);
+  assert.equal(cleared.dayId, null);
+  assert.equal(cleared.stopId, null);
+  assert.equal(cleared.text, "Base");
+});
+
+test("store saves, edits, and looks up notes by day or stop", () => {
+  const store = createNotesStore([
+    { id: "note-1", text: "Semilla", dayId: "day-1" }
+  ]);
+
+  const saved = store.save({ id: "note-2", text: "Nueva", stopId: "stop-7" });
+  const edited = store.update("note-1", { text: "Semilla editada", dayId: "day-2" });
+
+  assert.equal(saved.id, "note-2");
+  assert.equal(saved.stopId, "stop-7");
+  assert.equal(edited.text, "Semilla editada");
+  assert.deepEqual(store.listForDay("day-2").map((note) => note.id), ["note-1"]);
+  assert.deepEqual(store.listForStop("stop-7").map((note) => note.id), ["note-2"]);
+  assert.deepEqual(getNote(store.snapshot(), "note-1"), edited);
+  assert.deepEqual(listNotesForDay(store.snapshot(), "day-2"), [edited]);
+  assert.deepEqual(listNotesForStop(store.snapshot(), "stop-7"), [saved]);
+});

diff --git a/src/itinerario/stops/stops.mjs b/src/itinerario/stops/stops.mjs
new file mode 100644
index 0000000000000000000000000000000000000000..ecf0c155dfe12f8ad9bde571f893f17329d34064
--- /dev/null
+++ b/src/itinerario/stops/stops.mjs
@@ -0,0 +1,239 @@
+const STOP_KEYS = ["id", "name", "startDate", "endDate", "description", "order"];
+
+function isRecord(value) {
+  return typeof value === "object" && value !== null && !Array.isArray(value);
+}
+
+function toInteger(value) {
+  return Number.isInteger(value) ? value : Number.parseInt(value, 10);
+}
+
+function clamp(value, min, max) {
+  return Math.min(Math.max(value, min), max);
+}
+
+function createId() {
+  if (typeof crypto !== "undefined" && typeof crypto.randomUUID === "function") {
+    return crypto.randomUUID();
+  }
+
+  return `stop-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
+}
+
+function cloneStop(stop) {
+  return {
+    id: stop.id,
+    name: stop.name,
+    startDate: stop.startDate,
+    endDate: stop.endDate,
+    description: stop.description,
+    order: stop.order
+  };
+}
+
+function normalizeStops(stops) {
+  return (Array.isArray(stops) ? stops : [])
+    .map((stop, index) => ({
+      stop: cloneStop(stop),
+      index
+    }))
+    .sort((left, right) => {
+      const orderDifference = toInteger(left.stop.order) - toInteger(right.stop.order);
+      if (orderDifference !== 0) {
+        return orderDifference;
+      }
+
+      return left.index - right.index;
+    })
+    .map(({ stop }, index) => ({
+      id: stop.id,
+      name: stop.name,
+      startDate: stop.startDate,
+      endDate: stop.endDate,
+      description: stop.description,
+      order: index + 1
+    }));
+}
+
+function buildStop(stop, order, id = createId()) {
+  return {
+    id,
+    name: stop?.name ?? "",
+    startDate: stop?.startDate ?? "",
+    endDate: stop?.endDate ?? "",
+    description: stop?.description ?? "",
+    order
+  };
+}
+
+function insertAtOrder(stops, stop, order) {
+  const normalized = normalizeStops(stops);
+  const insertionIndex = clamp((Number(order) || normalized.length + 1) - 1, 0, normalized.length);
+  const next = normalized.slice();
+  next.splice(insertionIndex, 0, stop);
+
+  return next.map((entry, index) => ({
+    id: entry.id,
+    name: entry.name,
+    startDate: entry.startDate,
+    endDate: entry.endDate,
+    description: entry.description,
+    order: index + 1
+  }));
+}
+
+function findStopIndex(stops, stopId) {
+  return stops.findIndex((stop) => stop.id === stopId);
+}
+
+function resolveMoveIndexes(stops, source, target) {
+  if (isRecord(source)) {
+    const fromId = source.fromId ?? source.id;
+    const toId = source.toId ?? source.beforeId ?? target;
+    if (typeof fromId === "string" && typeof toId === "string") {
+      return resolveMoveIndexes(stops, fromId, toId);
+    }
+
+    const fromIndex = source.fromIndex ?? source.fromOrder;
+    const toIndex = source.toIndex ?? source.toOrder;
+    if (fromIndex !== undefined && toIndex !== undefined) {
+      return resolveMoveIndexes(stops, fromIndex, toIndex);
+    }
+
+    const afterId = source.afterId;
+    if (typeof fromId === "string" && typeof afterId === "string") {
+      const afterIndex = findStopIndex(stops, afterId);
+      if (afterIndex < 0) {
+        throw new RangeError(`Stop not found: ${afterId}`);
+      }
+      return {
+        fromIndex: findStopIndex(stops, fromId),
+        toIndex: afterIndex + 1
+      };
+    }
+  }
+
+  if (typeof source === "string" && typeof target === "string") {
+    return {
+      fromIndex: findStopIndex(stops, source),
+      toIndex: findStopIndex(stops, target)
+    };
+  }
+
+  const fromValue = toInteger(source);
+  const toValue = toInteger(target);
+  if (Number.isInteger(fromValue) && Number.isInteger(toValue)) {
+    const base = fromValue === 0 || toValue === 0 ? 0 : 1;
+    return {
+      fromIndex: fromValue - base,
+      toIndex: toValue - base
+    };
+  }
+
+  throw new TypeError("Unsupported reorder arguments");
+}
+
+function moveStop(stops, fromIndex, toIndex) {
+  if (!Number.isInteger(fromIndex) || !Number.isInteger(toIndex)) {
+    throw new TypeError("Reorder positions must be integers");
+  }
+
+  if (fromIndex < 0 || fromIndex >= stops.length) {
+    throw new RangeError(`Stop index out of range: ${fromIndex}`);
+  }
+
+  const next = normalizeStops(stops);
+  const [item] = next.splice(fromIndex, 1);
+  const insertionIndex = clamp(toIndex, 0, next.length);
+  next.splice(insertionIndex, 0, item);
+
+  return next.map((entry, index) => ({
+    id: entry.id,
+    name: entry.name,
+    startDate: entry.startDate,
+    endDate: entry.endDate,
+    description: entry.description,
+    order: index + 1
+  }));
+}
+
+function locateStop(stops, stopId) {
+  const normalized = normalizeStops(stops);
+  const index = findStopIndex(normalized, stopId);
+  if (index < 0) {
+    throw new RangeError(`Stop not found: ${stopId}`);
+  }
+
+  return { normalized, index };
+}
+
+export function addStop(stops, stop) {
+  const normalized = normalizeStops(stops);
+  const nextStop = buildStop(stop, Number.isFinite(stop?.order) ? stop.order : normalized.length + 1, stop?.id);
+  return insertAtOrder(normalized, nextStop, nextStop.order);
+}
+
+export function editStop(stops, stopId, changes) {
+  const { normalized, index } = locateStop(stops, stopId);
+  const current = normalized[index];
+  const updated = {
+    id: current.id,
+    name: changes?.name ?? current.name,
+    startDate: changes?.startDate ?? current.startDate,
+    endDate: changes?.endDate ?? current.endDate,
+    description: changes?.description ?? current.description,
+    order: current.order
+  };
+
+  const next = normalized.slice();
+  next.splice(index, 1);
+
+  if (changes && Object.prototype.hasOwnProperty.call(changes, "order")) {
+    return insertAtOrder(next, updated, changes.order);
+  }
+
+  next.splice(index, 0, updated);
+  return next.map((entry, position) => ({
+    id: entry.id,
+    name: entry.name,
+    startDate: entry.startDate,
+    endDate: entry.endDate,
+    description: entry.description,
+    order: position + 1
+  }));
+}
+
+export function removeStop(stops, stopId) {
+  const normalized = normalizeStops(stops);
+  const index = findStopIndex(normalized, stopId);
+  if (index < 0) {
+    throw new RangeError(`Stop not found: ${stopId}`);
+  }
+
+  return normalized
+    .filter((_, position) => position !== index)
+    .map((entry, position) => ({
+      id: entry.id,
+      name: entry.name,
+      startDate: entry.startDate,
+      endDate: entry.endDate,
+      description: entry.description,
+      order: position + 1
+    }));
+}
+
+export function reorderStops(stops, source, target) {
+  const normalized = normalizeStops(stops);
+  const { fromIndex, toIndex } = resolveMoveIndexes(normalized, source, target);
+  if (fromIndex < 0 || fromIndex >= normalized.length) {
+    throw new RangeError(`Stop not found at source position: ${fromIndex}`);
+  }
+
+  if (toIndex < 0) {
+    throw new RangeError(`Stop position out of range: ${toIndex}`);
+  }
+
+  return moveStop(normalized, fromIndex, toIndex);
+}
+
+export const stopFields = STOP_KEYS.slice();
