+import assert from "node:assert/strict";
+import test from "node:test";
+import {
+  addItem,
+  calculateTotalProgress,
+  crearChecklistEquipaje,
+  completeItem,
+  filterItems
+} from "./packing.mjs";
+
+test("Checklist de equipaje adds, completes, filters, and reports progress", () => {
+  const checklist = crearChecklistEquipaje(["Campera"]);
+
+  assert.equal(checklist.items.length, 1);
+  assert.deepEqual(checklist.items[0], { label: "Campera", completed: false });
+
+  const added = checklist.agregarItem("Pasaporte");
+  assert.deepEqual(added, { label: "Pasaporte", completed: false });
+  assert.equal(checklist.items.length, 2);
+
+  const completed = checklist.completarItem("Campera");
+  assert.deepEqual(completed, { label: "Campera", completed: true });
+  assert.equal(checklist.items[0].completed, true);
+
+  const pendingItems = checklist.filtrarItems({ completed: false });
+  assert.deepEqual(pendingItems, [{ label: "Pasaporte", completed: false }]);
+
+  const searchItems = checklist.filterItems({ query: "pas" });
+  assert.deepEqual(searchItems, [{ label: "Pasaporte", completed: false }]);
+
+  assert.equal(checklist.calcularProgresoTotal(), 50);
+});
+
+test("the module-level helpers work with the canonical Checklist de equipaje shape", () => {
+  const checklist = crearChecklistEquipaje();
+
+  addItem(checklist, "Toalla");
+  addItem(checklist, { nombre: "Medicamentos" });
+  completeItem(checklist, "Medicamentos");
+
+  assert.deepEqual(filterItems(checklist, { status: "pending" }), [{ label: "Toalla", completed: false }]);
+  assert.equal(calculateTotalProgress(checklist), 50);
+});

