+  if (filter.dayId !== undefined && filter.dayId !== null && String(filter.dayId).trim() !== note.dayId) {
+    return false;
+  }
+  if (filter.stopId !== undefined && filter.stopId !== null && String(filter.stopId).trim() !== note.stopId) {
+    return false;
+  }
+  return true;
+}
+
+export function createNote(input, now = new Date()) {
+  return normalizeNote(input, now);
+}
+
+export function updateNote(note, patch, now = new Date()) {
+  return applyPatch(normalizeNote(note, new Date(note.updatedAt ?? now)), patch, now);
+}
+
+export function associateNote(note, association, now = new Date()) {
+  return applyPatch(note, association, now);
+}
+
+export function disassociateNote(note, now = new Date()) {
+  if (!note || typeof note !== "object") {
+    throw new TypeError("A note must be an object.");
+  }
+  return cloneNote({
+    ...note,
+    dayId: null,
+    stopId: null,
+    updatedAt: now.toISOString()
+  });
+}
+
+export function listNotes(notes = [], filter = {}) {
+  return notes.filter((note) => matchesFilter(note, filter)).map(cloneNote);
+}
+
+export function listNotesForDay(notes = [], dayId) {
+  return listNotes(notes, { dayId });
+}
+
+export function listNotesForStop(notes = [], stopId) {
+  return listNotes(notes, { stopId });
+}
+
+export function getNote(notes = [], id) {
+  const noteId = normalizeId(id);
+  const found = notes.find((note) => note.id === noteId);
+  return found ? cloneNote(found) : null;
+}
+
+export function createNotesStore(initialNotes = []) {
+  const state = new Map();
