+  for (const note of initialNotes) {
+    const normalized = normalizeNote(note);
+    state.set(normalized.id, normalized);
+  }
+
+  const store = {
+    save(input) {
+      if (input?.id) {
+        const noteId = normalizeId(input.id);
+        const existing = state.get(noteId);
+        const candidate = existing ? applyPatch(existing, input) : normalizeNote(input);
+        state.set(candidate.id, candidate);
+        return cloneNote(candidate);
+      }
+
+      const candidate = normalizeNote(input);
+      state.set(candidate.id, candidate);
+      return cloneNote(candidate);
+    },
+    update(id, patch) {
+      const noteId = normalizeId(id);
+      const existing = state.get(noteId);
+      if (!existing) {
+        throw new RangeError(`Note not found: ${noteId}`);
