+  return (Array.isArray(stops) ? stops : [])
+    .map((stop, index) => ({
+      stop: cloneStop(stop),
+      index
+    }))
+    .sort((left, right) => {
+      const orderDifference = toInteger(left.stop.order) - toInteger(right.stop.order);
+      if (orderDifference !== 0) {
+        return orderDifference;
+      }
