+        throw new RangeError(`Stop not found: ${afterId}`);
+      }
+      return {
+        fromIndex: findStopIndex(stops, fromId),
+        toIndex: afterIndex + 1
+      };
+    }
+  }
+
+  if (typeof source === "string" && typeof target === "string") {
+    return {
+      fromIndex: findStopIndex(stops, source),
+      toIndex: findStopIndex(stops, target)
