+import assert from "node:assert/strict";
+import test from "node:test";
+import {
+  associateNote,
+  createNote,
+  createNotesStore,
+  disassociateNote,
+  getNote,
+  listNotesForDay,
+  listNotesForStop,
+  updateNote
+} from "./notes.mjs";
+
+test("creates a note associated to a day", () => {
+  const note = createNote({ text: "Comprar agua", dayId: "day-1" });
+
+  assert.equal(note.text, "Comprar agua");
+  assert.equal(note.dayId, "day-1");
+  assert.equal(note.stopId, null);
+  assert.match(note.id, /^[0-9a-f-]{36}$/);
+  assert.ok(note.createdAt);
+  assert.equal(note.createdAt, note.updatedAt);
+});
+
+test("creates a note associated to a stop", () => {
+  const note = createNote({ texto: "Sacar foto", paradaId: "stop-9" });
+
+  assert.equal(note.text, "Sacar foto");
+  assert.equal(note.dayId, null);
+  assert.equal(note.stopId, "stop-9");
+});
+
+test("rejects notes without exactly one association", () => {
+  assert.throws(() => createNote({ text: "Sin destino" }), /exactly one day or stop/);
+  assert.throws(() => createNote({ text: "Dos destinos", dayId: "day-1", stopId: "stop-2" }), /exactly one day or stop/);
+});
+
+test("updates the note text and association", () => {
+  const created = createNote({ text: "Original", dayId: "day-1" });
+  const updated = updateNote(created, { text: "Editada", stopId: "stop-2" });
+
+  assert.equal(updated.id, created.id);
+  assert.equal(updated.text, "Editada");
+  assert.equal(updated.dayId, null);
+  assert.equal(updated.stopId, "stop-2");
+  assert.notEqual(updated.updatedAt, created.updatedAt);
+});
+
+test("associates and disassociates notes without losing the text", () => {
+  const created = createNote({ text: "Base", dayId: "day-1" });
+  const moved = associateNote(created, { stopId: "stop-3" });
+  const cleared = disassociateNote(moved);
+
+  assert.equal(moved.stopId, "stop-3");
+  assert.equal(moved.dayId, null);
+  assert.equal(cleared.dayId, null);
+  assert.equal(cleared.stopId, null);
+  assert.equal(cleared.text, "Base");
+});
+
+test("store saves, edits, and looks up notes by day or stop", () => {
+  const store = createNotesStore([
+    { id: "note-1", text: "Semilla", dayId: "day-1" }
+  ]);
+
+  const saved = store.save({ id: "note-2", text: "Nueva", stopId: "stop-7" });
+  const edited = store.update("note-1", { text: "Semilla editada", dayId: "day-2" });
+
+  assert.equal(saved.id, "note-2");
+  assert.equal(saved.stopId, "stop-7");
+  assert.equal(edited.text, "Semilla editada");
+  assert.deepEqual(store.listForDay("day-2").map((note) => note.id), ["note-1"]);
+  assert.deepEqual(store.listForStop("stop-7").map((note) => note.id), ["note-2"]);
+  assert.deepEqual(getNote(store.snapshot(), "note-1"), edited);
+  assert.deepEqual(listNotesForDay(store.snapshot(), "day-2"), [edited]);
+  assert.deepEqual(listNotesForStop(store.snapshot(), "stop-7"), [saved]);
+});

