+function isRecord(value) {
+  return typeof value === "object" && value !== null && !Array.isArray(value);
+}
+
+function createId() {
+  if (typeof crypto !== "undefined" && typeof crypto.randomUUID === "function") {
+    return crypto.randomUUID();
+  }
+
+  return `activity-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
+}
+
+function cloneActivity(activity) {
+  return {
+    id: activity.id,
+    stopId: activity.stopId,
+    day: activity.day,
+    time: activity.time,
+    title: activity.title,
+    status: activity.status
+  };
+}
+
+function normalizeStatus(status) {
+  if (status === "completed" || status === "pending") {
+    return status;
+  }
+
+  if (status === "completada" || status === "pendiente") {
+    return status;
+  }
+
+  return "pendiente";
+}
+
+function toggleActivityStatus(status) {
+  if (status === "completed") {
+    return "pending";
+  }
+
+  if (status === "pending") {
+    return "completed";
+  }
+
+  if (status === "completada") {
+    return "pendiente";
+  }
+
+  if (status === "pendiente") {
+    return "completada";
+  }
+
+  return "completada";
+}
+
+function normalizeActivities(activities) {
+  return (Array.isArray(activities) ? activities : []).map((activity) => ({
+    id: activity.id,
+    stopId: activity.stopId,
+    day: activity.day,
+    time: activity.time,
+    title: activity.title,
+    status: normalizeStatus(activity.status)
+  }));
+}
+
+function buildActivity(activity, id = createId()) {
+  return {
+    id,
+    stopId: activity?.stopId ?? "",
+    day: activity?.day ?? "",
+    time: activity?.time ?? "",
+    title: activity?.title ?? "",
+    status: normalizeStatus(activity?.status)
+  };
+}
+
+function findActivityIndex(activities, activityId) {
+  return activities.findIndex((activity) => activity.id === activityId);
+}
+
+function locateActivity(activities, activityId) {
+  const normalized = normalizeActivities(activities);
+  const index = findActivityIndex(normalized, activityId);
+
+  if (index < 0) {
+    throw new RangeError(`Activity not found: ${activityId}`);
+  }
+
+  return { normalized, index };
+}
+
+export function addActivity(activities, activity) {
+  const normalized = normalizeActivities(activities);
+  const nextActivity = buildActivity(activity, activity?.id);
+
+  return normalized.concat(nextActivity).map(cloneActivity);
+}
+
+export function editActivity(activities, activityId, changes) {
+  const { normalized, index } = locateActivity(activities, activityId);
+  const current = normalized[index];
+  const updated = {
+    id: current.id,
+    stopId: changes?.stopId ?? current.stopId,
+    day: changes?.day ?? current.day,
+    time: changes?.time ?? current.time,
+    title: changes?.title ?? current.title,
+    status: Object.prototype.hasOwnProperty.call(changes ?? {}, "status")
+      ? normalizeStatus(changes.status)
+      : current.status
+  };
+
+  const next = normalized.slice();
+  next.splice(index, 1, updated);
+
+  return next.map(cloneActivity);
+}
+
+export function removeActivity(activities, activityId) {
+  const normalized = normalizeActivities(activities);
+  const index = findActivityIndex(normalized, activityId);
+
+  if (index < 0) {
+    throw new RangeError(`Activity not found: ${activityId}`);
+  }
+
+  return normalized.filter((_, position) => position !== index).map(cloneActivity);
+}
+
+export function toggleStatus(activities, activityId) {
+  const { normalized, index } = locateActivity(activities, activityId);
+  const current = normalized[index];
+  const updated = {
+    id: current.id,
+    stopId: current.stopId,
+    day: current.day,
+    time: current.time,
+    title: current.title,
+    status: toggleActivityStatus(current.status)
+  };
+
+  const next = normalized.slice();
+  next.splice(index, 1, updated);
+
+  return next.map(cloneActivity);
+}
