+import { crearPresupuesto } from "../budget/budget.mjs";
+import { crearChecklistEquipaje } from "../packing/packing.mjs";
+
+function crearResumenPresupuesto(presupuesto) {
+  return {
+    total: presupuesto.total,
+    gastado: presupuesto.gastado,
+    disponible: presupuesto.disponible,
+    gastosPorCategoria: { ...(presupuesto.gastosPorCategoria ?? {}) },
+  };
+}
+
+function resolverChecklist({ checklist, equipaje } = {}) {
+  return checklist ?? equipaje ?? crearChecklistEquipaje();
+}
+
+export function getOrganizationView({ presupuesto, checklist, equipaje } = {}) {
+  const presupuestoBase = presupuesto ?? crearPresupuesto(0);
+  const checklistBase = resolverChecklist({ checklist, equipaje });
+
+  return {
+    presupuesto: crearResumenPresupuesto(presupuestoBase),
+    progresoEquipaje: checklistBase.calcularProgresoTotal(),
+  };
+}
+
+export default {
+  getOrganizationView,
+};

