+import assert from "node:assert/strict";
+import test from "node:test";
+
+import { addActivity, editActivity, removeActivity, toggleStatus } from "./agenda.mjs";
+
+function makeActivity(overrides = {}) {
+  return {
+    id: "activity-1",
+    stopId: "stop-1",
+    day: "2026-08-21",
+    time: "09:00",
+    title: "Salida hacia la playa",
+    status: "pendiente",
+    ...overrides
+  };
+}
+
+function assertActivityShape(activity) {
+  assert.deepEqual(Object.keys(activity), ["id", "stopId", "day", "time", "title", "status"]);
+}
+
+test("addActivity creates an activity tied to a stop and day", () => {
+  const activities = [makeActivity()];
+
+  const next = addActivity(activities, {
+    stopId: "stop-2",
+    day: "2026-08-22",
+    time: "13:30",
+    title: "Almuerzo",
+    status: "completada"
+  });
+
+  assert.equal(next.length, 2);
+  assertActivityShape(next[0]);
+  assertActivityShape(next[1]);
+  assert.equal(next[1].stopId, "stop-2");
+  assert.equal(next[1].day, "2026-08-22");
+  assert.equal(next[1].time, "13:30");
+  assert.equal(next[1].title, "Almuerzo");
+  assert.equal(next[1].status, "completada");
+  assert.equal(typeof next[1].id, "string");
+});
+
+test("editActivity updates the linked stop, day, time, title, and status", () => {
+  const activities = [makeActivity(), makeActivity({ id: "activity-2", stopId: "stop-2", title: "Cena" })];
+
+  const next = editActivity(activities, "activity-2", {
+    stopId: "stop-3",
+    day: "2026-08-23",
+    time: "20:00",
+    title: "Cena de despedida",
+    status: "completada"
+  });
+
+  assert.equal(next[1].stopId, "stop-3");
+  assert.equal(next[1].day, "2026-08-23");
+  assert.equal(next[1].time, "20:00");
+  assert.equal(next[1].title, "Cena de despedida");
+  assert.equal(next[1].status, "completed");
+  assertActivityShape(next[1]);
+});
+
+test("editActivity preserves status when it is not provided", () => {
+  const activities = [makeActivity({ id: "activity-2", status: "completada" })];
+
+  const next = editActivity(activities, "activity-2", {
+    title: "Salida tardía"
+  });
+
+  assert.equal(next[0].status, "completada");
+  assert.equal(next[0].title, "Salida tardía");
+});
+
+test("removeActivity deletes an activity", () => {
+  const activities = [
+    makeActivity({ id: "activity-1", title: "A" }),
+    makeActivity({ id: "activity-2", title: "B" }),
+    makeActivity({ id: "activity-3", title: "C" })
+  ];
+
+  const next = removeActivity(activities, "activity-2");
+
+  assert.deepEqual(next.map((activity) => activity.title), ["A", "C"]);
+  assert.deepEqual(next.map((activity) => activity.status), ["pendiente", "pendiente"]);
+});
+
+test("toggleStatus switches between pending and completed", () => {
+  const activities = [
+    makeActivity({ id: "activity-1", status: "pendiente" }),
+    makeActivity({ id: "activity-2", status: "completada" })
+  ];
+
+  const next = toggleStatus(activities, "activity-1");
+  const nextAgain = toggleStatus(next, "activity-2");
+
+  assert.equal(next[0].status, "completada");
+  assert.equal(nextAgain[1].status, "pendiente");
+  assertActivityShape(next[0]);
+  assertActivityShape(nextAgain[1]);
+});

