+  return {
+    id: stop.id,
+    name: stop.name,
+    startDate: stop.startDate,
+    endDate: stop.endDate,
+    description: stop.description,
+    order: stop.order
+  };
+}
+
+function cloneActivity(activity) {
+  return {
+    id: activity.id,
+    stopId: activity.stopId,
+    day: activity.day,
+    time: activity.time,
+    title: activity.title,
+    status: activity.status
+  };
+}
+
+function normalizeText(value) {
+  return String(value ?? "")
+    .normalize("NFD")
+    .replace(/[\u0300-\u036f]/g, "")
+    .toLowerCase();
+}
+
+function matchesText(fields, query) {
+  const normalizedQuery = normalizeText(query).trim();
+  if (normalizedQuery === "") {
+    return true;
+  }
+
+  return fields.some((field) => normalizeText(field).includes(normalizedQuery));
+}
+
+function normalizeKind(value) {
+  const kind = normalizeText(value);
+
+  if (["stop", "stops", "parada", "paradas"].includes(kind)) {
+    return "stops";
+  }
+
+  if (["activity", "activities", "actividad", "actividades"].includes(kind)) {
+    return "activities";
+  }
+
+  return "all";
+}
+
+function matchesStopCriteria(stop, criteria) {
+  const query = criteria?.query ?? criteria?.search ?? criteria?.term ?? "";
+  if (!matchesText([stop.id, stop.name, stop.startDate, stop.endDate, stop.description, stop.order], query)) {
+    return false;
+  }
+
+  if (criteria?.startDate !== undefined && stop.startDate !== criteria.startDate) {
+    return false;
+  }
+
+  if (criteria?.endDate !== undefined && stop.endDate !== criteria.endDate) {
+    return false;
+  }
+
+  if (criteria?.order !== undefined && String(stop.order) !== String(criteria.order)) {
+    return false;
+  }
+
+  return true;
+}
+
+function matchesActivityCriteria(activity, criteria) {
+  const query = criteria?.query ?? criteria?.search ?? criteria?.term ?? "";
+  if (!matchesText([activity.id, activity.stopId, activity.day, activity.time, activity.title, activity.status], query)) {
+    return false;
+  }
+
+  if (criteria?.stopId !== undefined && activity.stopId !== criteria.stopId) {
+    return false;
+  }
+
+  if (criteria?.day !== undefined && activity.day !== criteria.day) {
+    return false;
+  }
+
+  if (criteria?.status !== undefined && activity.status !== criteria.status) {
+    return false;
+  }
+
+  return true;
+}
+
+function filterStops(stops, criteria = {}) {
+  const kind = normalizeKind(criteria.kind ?? criteria.type);
+  if (kind === "activities") {
+    return [];
+  }
+
+  return toArray(stops).filter((stop) => matchesStopCriteria(stop, criteria)).map(cloneStop);
+}
+
+function filterActivities(activities, criteria = {}) {
+  const kind = normalizeKind(criteria.kind ?? criteria.type);
+  if (kind === "stops") {
+    return [];
+  }
+
+  return toArray(activities).filter((activity) => matchesActivityCriteria(activity, criteria)).map(cloneActivity);
+}
+
+export function searchStops(stops, query) {
+  return filterStops(stops, { query });
+}
+
+export function searchActivities(activities, query) {
+  return filterActivities(activities, { query });
+}
+
+export function filterExploration(stops, activities, criteria = {}) {
+  return {
+    stops: filterStops(stops, criteria),
+    activities: filterActivities(activities, criteria)
+  };
+}
+
+export function searchExploration(stops, activities, query) {
+  return filterExploration(stops, activities, { query });
+}
+
+export function exploreItinerary(stops, activities, criteria = {}) {
+  return filterExploration(stops, activities, criteria);
+}
