index 0000000000000000000000000000000000000000..7d219590b5cedf1b505dd432fb832757affd21de
--- /dev/null
+++ b/src/itinerario/exploration/exploration.mjs
@@ -0,0 +1,189 @@
+function isRecord(value) {
+  return typeof value === "object" && value !== null && !Array.isArray(value);
+}
+
+function cloneStop(stop) {
+  return {
+    id: stop.id,
+    name: stop.name,
+    startDate: stop.startDate,
+    endDate: stop.endDate,
+    description: stop.description,
+    order: stop.order
+  };
+}
+
+function cloneActivity(activity) {
+  return {
+    id: activity.id,
+    stopId: activity.stopId,
+    day: activity.day,
+    time: activity.time,
+    title: activity.title,
+    status: activity.status
+  };
+}
+
+function normalizeText(value) {
+  return String(value ?? "")
+    .normalize("NFD")
+    .replace(/\p{Diacritic}/gu, "")
+    .toLowerCase()
+    .trim();
+}
+
+function matchesQuery(value, query) {
+  const needle = normalizeText(query);
+  if (!needle) {
+    return true;
+  }
+
+  return normalizeText(value).includes(needle);
+}
+
+function filterByFields(items, query, fields) {
+  return (Array.isArray(items) ? items : [])
+    .filter((item) =>
+      !query ||
+      fields.some((field) => matchesQuery(item?.[field], query))
+    )
+    .map((item) => item.kind === "activity" ? cloneActivity(item) : cloneStop(item));
+}
+
+function normalizeStopCriteria(criteria) {
+  if (typeof criteria === "string") {
+    return { query: criteria };
+  }
+
+  return isRecord(criteria) ? criteria : {};
+}
+
+function normalizeActivityCriteria(criteria) {
+  if (typeof criteria === "string") {
+    return { query: criteria };
+  }
+
+  return isRecord(criteria) ? criteria : {};
+}
+
+export function searchStops(stops, query = "") {
+  return filterStops(stops, { query });
+}
+
+export function filterStops(stops, criteria = {}) {
+  const normalizedCriteria = normalizeStopCriteria(criteria);
+  const query = normalizedCriteria.query ?? "";
+  const startDate = normalizedCriteria.startDate;
+  const endDate = normalizedCriteria.endDate;
+
+  return (Array.isArray(stops) ? stops : [])
+    .filter((stop) => {
+      if (query && ![
+        stop?.name,
+        stop?.description,
+        stop?.startDate,
+        stop?.endDate
+      ].some((value) => matchesQuery(value, query))) {
+        return false;
+      }
+
+      if (startDate !== undefined && stop?.startDate !== startDate) {
+        return false;
+      }
+
+      if (endDate !== undefined && stop?.endDate !== endDate) {
+        return false;
+      }
+
+      return true;
+    })
+    .map(cloneStop);
+}
+
+export function searchActivities(activities, query = "") {
+  return filterActivities(activities, { query });
+}
+
+export function filterActivities(activities, criteria = {}) {
+  const normalizedCriteria = normalizeActivityCriteria(criteria);
+  const query = normalizedCriteria.query ?? "";
+  const stopId = normalizedCriteria.stopId;
+  const day = normalizedCriteria.day;
+  const time = normalizedCriteria.time;
+  const status = normalizedCriteria.status;
+
+  return (Array.isArray(activities) ? activities : [])
+    .filter((activity) => {
+      if (query && ![
+        activity?.title,
+        activity?.stopId,
+        activity?.day,
+        activity?.time,
+        activity?.status
+      ].some((value) => matchesQuery(value, query))) {
+        return false;
+      }
+
+      if (stopId !== undefined && activity?.stopId !== stopId) {
+        return false;
+      }
+
+      if (day !== undefined && activity?.day !== day) {
+        return false;
+      }
+
+      if (time !== undefined && activity?.time !== time) {
+        return false;
+      }
+
+      if (status !== undefined && activity?.status !== status) {
+        return false;
+      }
+
+      return true;
+    })
+    .map(cloneActivity);
+}
+
+export function exploreStops(stops, criteria = {}) {
+  return filterStops(stops, criteria);
+}
+
+export function exploreActivities(activities, criteria = {}) {
+  return filterActivities(activities, criteria);
+}
+
+export function exploreItinerary(stopsOrItinerary, activitiesOrCriteria = {}, maybeCriteria = {}) {
+  if (isRecord(stopsOrItinerary) && (Array.isArray(stopsOrItinerary.stops) || Array.isArray(stopsOrItinerary.activities))) {
+    const itinerary = stopsOrItinerary;
+    const criteria = isRecord(activitiesOrCriteria) ? activitiesOrCriteria : {};
+
+    return {
+      stops: exploreStops(itinerary.stops, criteria),
+      activities: exploreActivities(itinerary.activities, criteria)
+    };
+  }
+
+  const stops = Array.isArray(stopsOrItinerary) ? stopsOrItinerary : [];
+  const activities = Array.isArray(activitiesOrCriteria) ? activitiesOrCriteria : [];
+  const criteria = isRecord(maybeCriteria) ? maybeCriteria : {};
+
+  return {
+    stops: exploreStops(stops, criteria),
+    activities: exploreActivities(activities, criteria)
+  };
+}
+
+export function filterItinerary(stopsOrItinerary, activitiesOrCriteria = {}, maybeCriteria = {}) {
+  return exploreItinerary(stopsOrItinerary, activitiesOrCriteria, maybeCriteria);
+}
+
+export function searchItinerary(stopsOrItinerary, query = "") {
+  const criteria = typeof query === "string" ? { query } : query;
+
+  if (isRecord(stopsOrItinerary) && (Array.isArray(stopsOrItinerary.stops) || Array.isArray(stopsOrItinerary.activities))) {
+    return exploreItinerary(stopsOrItinerary, criteria);
+  }
+
+  return exploreItinerary(stopsOrItinerary, [], criteria);
+}
diff --git a/src/itinerario/exploration/exploration.test.mjs b/src/itinerario/exploration/exploration.test.mjs
new file mode 100644
index 0000000000000000000000000000000000000000..db7cde40528cf5c073b186d63af54529513634da
--- /dev/null
+++ b/src/itinerario/exploration/exploration.test.mjs
@@ -0,0 +1,146 @@
+import assert from "node:assert/strict";
+import test from "node:test";
+
+import {
+  exploreActivities,
+  exploreItinerary,
+  exploreStops,
+  filterActivities,
+  filterStops,
+  searchActivities,
+  searchItinerary,
+  searchStops
+} from "./exploration.mjs";
+
+function makeStop(overrides = {}) {
+  return {
+    id: "stop-1",
+    name: "Montevideo",
+    startDate: "2026-08-01",
+    endDate: "2026-08-03",
+    description: "Base de partida",
+    order: 1,
+    ...overrides
+  };
+}
+
+function makeActivity(overrides = {}) {
+  return {
+    id: "activity-1",
+    stopId: "stop-1",
+    day: "2026-08-21",
+    time: "09:00",
+    title: "Salida hacia la playa",
+    status: "pendiente",
+    ...overrides
+  };
+}
+
+function assertStopShape(stop) {
+  assert.deepEqual(Object.keys(stop), ["id", "name", "startDate", "endDate", "description", "order"]);
+}
+
+function assertActivityShape(activity) {
+  assert.deepEqual(Object.keys(activity), ["id", "stopId", "day", "time", "title", "status"]);
+}
+
+test("searchStops preserves itinerary order while matching by text", () => {
+  const stops = [
+    makeStop({ id: "a", name: "Playa", order: 1 }),
+    makeStop({ id: "b", name: "Centro", order: 2 }),
+    makeStop({ id: "c", name: "Parque", order: 3 })
+  ];
+
+  const next = searchStops(stops, "a");
+
+  assert.deepEqual(next.map((stop) => stop.id), ["a", "c"]);
+  assert.deepEqual(next.map((stop) => stop.order), [1, 3]);
+  assertStopShape(next[0]);
+  assertStopShape(next[1]);
+});
+
+test("filterStops keeps the original order and applies exact field filters", () => {
+  const stops = [
+    makeStop({ id: "a", name: "A", order: 1, startDate: "2026-08-01" }),
+    makeStop({ id: "b", name: "B", order: 2, startDate: "2026-08-02" }),
+    makeStop({ id: "c", name: "C", order: 3, startDate: "2026-08-01" })
+  ];
+
+  const next = filterStops(stops, { startDate: "2026-08-01" });
+
+  assert.deepEqual(next.map((stop) => stop.id), ["a", "c"]);
+  assert.deepEqual(next.map((stop) => stop.order), [1, 3]);
+});
+
+test("exploreStops returns clones and preserves the same order", () => {
+  const stops = [
+    makeStop({ id: "a", name: "A", order: 1 }),
+    makeStop({ id: "b", name: "B", order: 2 })
+  ];
+
+  const next = exploreStops(stops, { query: "b" });
+
+  assert.equal(next[0].id, "b");
+  assert.notEqual(next[0], stops[1]);
+  assertStopShape(next[0]);
+});
+
+test("searchActivities preserves the original order while matching query text", () => {
+  const activities = [
+    makeActivity({ id: "a", title: "Museo", day: "2026-08-21", time: "11:00" }),
+    makeActivity({ id: "b", title: "Almuerzo", day: "2026-08-21", time: "09:00" }),
+    makeActivity({ id: "c", title: "Cena", day: "2026-08-22", time: "20:00" })
+  ];
+
+  const next = searchActivities(activities, "2");
+
+  assert.deepEqual(next.map((activity) => activity.id), ["c"]);
+  assertActivityShape(next[0]);
+});
+
+test("filterActivities can narrow by status without changing the input order", () => {
+  const activities = [
+    makeActivity({ id: "a", title: "A", status: "pendiente" }),
+    makeActivity({ id: "b", title: "B", status: "completada" }),
+    makeActivity({ id: "c", title: "C", status: "completada" })
+  ];
+
+  const next = filterActivities(activities, { status: "completada" });
+
+  assert.deepEqual(next.map((activity) => activity.id), ["b", "c"]);
+  assert.deepEqual(next.map((activity) => activity.status), ["completada", "completada"]);
+});
+
+test("exploreItinerary filters both collections without reordering them", () => {
+  const stops = [
+    makeStop({ id: "a", name: "Puerto", order: 1 }),
+    makeStop({ id: "b", name: "Playa", order: 2 }),
+    makeStop({ id: "c", name: "Centro", order: 3 })
+  ];
+  const activities = [
+    makeActivity({ id: "x", stopId: "a", title: "Alquiler de bici" }),
+    makeActivity({ id: "y", stopId: "b", title: "Almuerzo" }),
+    makeActivity({ id: "z", stopId: "c", title: "Museo" })
+  ];
+
+  const next = exploreItinerary({ stops, activities }, { query: "o" });
+
+  assert.deepEqual(next.stops.map((stop) => stop.id), ["a", "c"]);
+  assert.deepEqual(next.activities.map((activity) => activity.id), ["x", "y"]);
+});
+
+test("searchItinerary accepts separate stop and activity arrays", () => {
+  const stops = [
+    makeStop({ id: "a", name: "A", order: 1 }),
+    makeStop({ id: "b", name: "B", order: 2 })
+  ];
+  const activities = [
+    makeActivity({ id: "x", title: "X" }),
+    makeActivity({ id: "y", title: "Y" })
+  ];
+
+  const next = searchItinerary(stops, activities, "y");
+
+  assert.deepEqual(next.stops.map((stop) => stop.id), []);
+  assert.deepEqual(next.activities.map((activity) => activity.id), ["y"]);
+});

