+}
+
+export function listNotes(notes = [], filter = {}) {
+  return (Array.isArray(notes) ? notes : [])
+    .filter((note) => matchesFilter(note, filter))
+    .map(cloneNote);
+}
+
+export function listNotesForDay(notes = [], dayId) {
+  return listNotes(notes, { dayId });
+}
+
+export function listNotesForStop(notes = [], stopId) {
+  return listNotes(notes, { stopId });
+}
+
+export function getNote(notes = [], id) {
+  const noteId = normalizeId(id);
+  const found = (Array.isArray(notes) ? notes : []).find((note) => note.id === noteId);
+  return found ? cloneNote(found) : null;
+}
+
+export function createNotesStore(initialNotes = []) {
+  const state = new Map();
+
+  for (const note of Array.isArray(initialNotes) ? initialNotes : []) {
+    const normalized = normalizeExistingNote(note);
+    state.set(normalized.id, normalized);
+  }
+
+  const store = {
+    save(input) {
+      if (input?.id !== undefined) {
+        const noteId = normalizeId(input.id);
+        const existing = state.get(noteId);
+        const candidate = existing ? applyPatch(existing, input) : buildNote({ ...input, id: noteId });
+        state.set(candidate.id, candidate);
+        return cloneNote(candidate);
+      }
+
+      const candidate = buildNote(input);
+      state.set(candidate.id, candidate);
+      return cloneNote(candidate);
+    },
+    update(id, patch) {
+      const noteId = normalizeId(id);
+      const existing = state.get(noteId);
+      if (!existing) {
+        throw new RangeError(`Note not found: ${noteId}`);
+      }
+
+      const updated = applyPatch(existing, patch);
+      state.set(noteId, updated);
+      return cloneNote(updated);
+    },
+    associate(id, association) {
+      return store.update(id, association);
+    },
+    disassociate(id) {
+      const noteId = normalizeId(id);
+      const existing = state.get(noteId);
+      if (!existing) {
+        throw new RangeError(`Note not found: ${noteId}`);
+      }
+
+      const updated = disassociateNote(existing);
+      state.set(noteId, updated);
+      return cloneNote(updated);
+    },
+    get(id) {
+      const noteId = normalizeId(id);
+      const note = state.get(noteId);
+      return note ? cloneNote(note) : null;
+    },
+    list(filter = {}) {
+      return listNotes([...state.values()], filter);
+    },
+    listForDay(dayId) {
+      return listNotesForDay([...state.values()], dayId);
+    },
+    listForStop(stopId) {
+      return listNotesForStop([...state.values()], stopId);
+    },
+    remove(id) {
+      const noteId = normalizeId(id);
+      const existing = state.get(noteId);
+      if (!existing) {
+        return false;
+      }
+
+      state.delete(noteId);
+      return true;
+    },
+    snapshot() {
+      return [...state.values()].map(cloneNote);
+    }
+  };
+
+  Object.defineProperties(store, {
+    edit: {
+      enumerable: false,
+      value(id, patch) {
+        return store.update(id, patch);
+      }
+    },
+    listByDay: {
+      enumerable: false,
+      value(dayId) {
+        return store.listForDay(dayId);
+      }
+    },
+    listByStop: {
+      enumerable: false,
+      value(stopId) {
+        return store.listForStop(stopId);
+      }
+    }
+  });
+
+  return store;
+}
+
+export const crearNota = createNote;
+export const actualizarNota = updateNote;
+export const editarNota = updateNote;
+export const asociarNota = associateNote;
+export const desasociarNota = disassociateNote;
+export const listarNotas = listNotes;
+export const listarNotasPorDia = listNotesForDay;
+export const listarNotasPorParada = listNotesForStop;
+export const obtenerNota = getNote;
+export const crearNotas = createNotesStore;
+export const guardarNotas = createNotesStore;
+export const createNoteStore = createNotesStore;
+export const listNotesByDay = listNotesForDay;
+export const listNotesByStop = listNotesForStop;
+export const getNoteById = getNote;
+
+export const notes = {
+  NOTE_KEYS,
+  createNote,
+  updateNote,
+  associateNote,
+  disassociateNote,
+  listNotes,
+  listNotesForDay,
+  listNotesForStop,
+  getNote,
+  createNotesStore,
+  crearNota,
+  actualizarNota,
+  editarNota,
+  asociarNota,
+  desasociarNota,
+  listarNotas,
+  listarNotasPorDia,
+  listarNotasPorParada,
+  obtenerNota,
+  crearNotas,
+  guardarNotas,
+  createNoteStore,
+  listNotesByDay,
+  listNotesByStop,
+  getNoteById
+};
+
+Object.defineProperties(notes, {
+  saveNote: {
+    enumerable: false,
+    value: createNote
+  },
+  guardarNota: {
+    enumerable: false,
+    value: createNote
+  },
+  editNote: {
+    enumerable: false,
+    value: updateNote
+  }
+});
+
+export default {
+  NOTE_KEYS,
+  createNote,
+  updateNote,
+  associateNote,
+  disassociateNote,
+  listNotes,
+  listNotesForDay,
+  listNotesForStop,
+  getNote,
+  createNotesStore,
+  crearNota,
+  actualizarNota,
+  editarNota,
+  asociarNota,
+  desasociarNota,
+  listarNotas,
+  listarNotasPorDia,
+  listarNotasPorParada,
+  obtenerNota,
+  crearNotas,
+  guardarNotas,
+  createNoteStore,
+  listNotesByDay,
+  listNotesByStop,
+  getNoteById,
+  notes
+};
diff --git a/src/recuerdos/notes/notes.test.mjs b/src/recuerdos/notes/notes.test.mjs
